// A movie or series, and the seasons and episodes under it.
func (q *Queries) UnmatchTargets(ctx context.Context, workID id.ID) ([]UnmatchTargetsRow, error) {
	rows, err := q.db.QueryContext(ctx, unmatchTargets, workID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []UnmatchTargetsRow
	for rows.Next() {
		var i UnmatchTargetsRow
		if err := rows.Scan(
			&i.ID,
			&i.Kind,
			&i.Title,
			&i.Number,
			&i.ParentNumber,
			&i.ReleaseDate,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

